//! cannot silently round-trip must be rewritten faithfully or reported, never skipped quietly.

#[path = "common/release_harness.rs"]
mod release_harness;

use std::{fs, path::Path};

use release_harness::*;

/// A two-crate Cargo workspace where `app-crate` depends on `lib-crate` with `dependency`.
fn cargo_workspace(dependency: &str) -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    callisto_fixtures::git::init_repo(root);
    fs::write(
        root.join("Cargo.toml"),
        "[workspace]\nmembers = [\"crates/lib\", \"crates/app\"]\nresolver = \"2\"\n",
    )
    .unwrap();
    for (name, extra) in [
        ("lib", String::new()),
        ("app", format!("\n[dependencies]\nlib-crate = {dependency}\n")),
    ] {
        fs::create_dir_all(root.join(format!("crates/{name}/src"))).unwrap();
        fs::write(
            root.join(format!("crates/{name}/Cargo.toml")),
            format!("[package]\nname = \"{name}-crate\"\nversion = \"0.1.0\"\nedition = \"2021\"\n{extra}"),
        )
        .unwrap();
        fs::write(root.join(format!("crates/{name}/src/lib.rs")), "pub fn f() {}\n").unwrap();
    }
    git(root, &["add", "."]);
    git(root, &["commit", "-q", "-m", "workspace"]);
    let init = callisto(root, &["init", "--yes", "--versioning", "independent", "--no-workflow"]);
    assert!(init.status.success(), "{}", String::from_utf8_lossy(&init.stderr));
    git(root, &["add", "."]);
    git(root, &["commit", "-q", "-m", "configure callisto"]);
    dir
}

fn add_changeset(root: &Path, package: &str, bump: &str) {
    let out = callisto(
        root,
        &["add", "--package", &format!("{package}:{bump}"), "--summary", "change"],
    );
    assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
    git(root, &["add", "."]);
    git(root, &["commit", "-q", "-m", "changeset"]);
}

fn read(root: &Path, path: &str) -> String {
    fs::read_to_string(root.join(path)).unwrap()
}

#[test]
fn an_exact_pin_is_rewritten_in_place_and_its_dependent_released() {
    let dir = cargo_workspace("{ version = \"=0.1.0\", path = \"../lib\" }");
use std::fs;
use std::process::Command;
use tempfile::tempdir;

/// Creates a temporary directory with a minimal polyglot git repository:
/// - a Cargo workspace with one crate (`core-crate` at 0.1.0)
/// - an npm `package.json` (`@myorg/web-app` at 1.0.0)
/// - an initial git commit
///
/// The directory is returned as a `TempDir`; dropping it cleans up disk.
pub fn setup_polyglot_git_repo() -> tempfile::TempDir {
    let dir = tempdir().unwrap();
    let root = dir.path();

    callisto_fixtures::git::init_repo(root);

    let cargo_toml = r#"[workspace]
members = ["crates/core"]
resolver = "2"
"#;
    fs::write(root.join("Cargo.toml"), cargo_toml).unwrap();

    fs::create_dir_all(root.join("crates/core/src")).unwrap();
    let crate_toml = r#"[package]
name = "core-crate"
version = "0.1.0"
edition = "2021"
description = "t"
license = "MIT"
"#;
    fs::write(root.join("crates/core/Cargo.toml"), crate_toml).unwrap();
    fs::write(root.join("crates/core/src/lib.rs"), "pub fn hello() {}\n").unwrap();

    fs::create_dir_all(root.join("packages/web")).unwrap();
    let pkg_json = r#"{
  "name": "@myorg/web-app",
  "version": "1.0.0"
}
"#;
    fs::write(root.join("packages/web/package.json"), pkg_json).unwrap();

    Command::new("git")
        .args(["add", "."])
        .current_dir(root)
        .status()
        .unwrap();
    Command::new("git")
        .args(["commit", "-m", "Initial commit"])
        .current_dir(root)
        .status()
        .unwrap();

    dir
}

