    let apply_opts = ApplyOptions {
        refresh_lockfiles: true,
        transient: true,
    };

    if let Some(permit) = ApplyPermit::granted_unless_dry_run(global.dry_run) {
        apply_version_plan(&ws.root, &plan, &runner, &apply_opts, &permit)?;
    }

