/// A two-crate workspace for `add --package` duplicate checks.
fn add_duplicate_workspace() -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    callisto_fixtures::git::init_repo(root);
    std::fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = [\"a\", \"b\"]\nresolver = \"2\"\n").unwrap();
    for name in ["a", "b"] {
        std::fs::create_dir_all(root.join(format!("{name}/src"))).unwrap();
        std::fs::write(
            root.join(format!("{name}/Cargo.toml")),
            format!("[package]\nname = \"{name}\"\nversion = \"0.1.0\"\nedition = \"2021\"\n"),
        )
        .unwrap();
        std::fs::write(root.join(format!("{name}/src/lib.rs")), "").unwrap();
    }
    std::fs::write(root.join("callisto.toml"), "").unwrap();
    dir
}

fn run_add(root: &std::path::Path, packages: &[&str]) -> std::process::Output {
    let mut cmd = std::process::Command::new(env!("CARGO_BIN_EXE_callisto"));
    cmd.args(["--cwd", root.to_str().unwrap(), "add", "--summary", "s"]);
    for p in packages {
        cmd.args(["--package", p]);
    }
    cmd.stdin(std::process::Stdio::null()).output().unwrap()
}

fn changeset_files(root: &std::path::Path) -> Vec<String> {
    std::fs::read_dir(root.join(".changeset"))
        .map(|d| {
            d.map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
                .filter(|n| n.ends_with(".md") && n != "README.md")
                .collect()
        })
        .unwrap_or_default()
}

#[test]
fn add_rejects_a_package_given_twice_and_writes_nothing() {
    let dir = add_duplicate_workspace();
    let root = dir.path();
    for packages in [["cargo/a:patch", "cargo/a:patch"], ["cargo/a:patch", "cargo/a:major"]] {
        let out = run_add(root, &packages);
        let stderr = String::from_utf8_lossy(&out.stderr);
        assert_eq!(out.status.code(), Some(1), "{packages:?}: {stderr}");
        assert!(stderr.contains("E325") && stderr.contains("cargo/a"), "{packages:?}: {stderr}");
        assert!(changeset_files(root).is_empty(), "{packages:?} must write nothing");
    }
}

#[test]
fn add_still_accepts_distinct_packages() {
    let dir = add_duplicate_workspace();
    let root = dir.path();
    let out = run_add(root, &["cargo/a:patch", "cargo/b:major"]);
    assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
    let files = changeset_files(root);
    assert_eq!(files.len(), 1);
    let text = std::fs::read_to_string(root.join(".changeset").join(&files[0])).unwrap();
    assert!(text.contains("a: patch") && text.contains("b: major"), "{text}");
}
